WEIGHTS = {"model_choice": 3, "enterprise_integration": 2, "data_residency": 2, "cost_flexibility": 1}

PLATFORMS = {
    "foundry": {"model_choice": 4, "enterprise_integration": 5, "data_residency": 4, "cost_flexibility": 3},
    "bedrock": {"model_choice": 4, "enterprise_integration": 4, "data_residency": 4, "cost_flexibility": 4},
    "vertex": {"model_choice": 4, "enterprise_integration": 3, "data_residency": 4, "cost_flexibility": 4},
}

def weighted_score(platform_scores):
    return sum(WEIGHTS[c] * platform_scores[c] for c in WEIGHTS)

totals = {name: weighted_score(scores) for name, scores in PLATFORMS.items()}
ranked = sorted(totals.items(), key=lambda kv: kv[1], reverse=True)
for name, score in ranked:
    print(f"{name}: {score}")
print(f"Recommended platform: {ranked[0][0]}")
